# Matemática I M20 (estadística y probabilidad): lección completa + 4 actividades por nivel (26/11/2026).
import sys; sys.path.insert(0,'tools/interactiva'); from armar import *
D=lambda md:m('datos',modo=md); DX=lambda md:m('datos_x',modo=md)
L={}
L['1']={"temas":[
 T("Contar y ordenar los datos",m('frecuencias'),m('tabla_frecuencias'),("Tabla de frecuencias","Una tabla de frecuencias ordena los datos de una encuesta o un registro: en una columna van los valores que aparecieron y en la otra, cuántas veces apareció cada uno, que es su frecuencia."),"Una lista de treinta respuestas sueltas no dice mucho; contada y ordenada en una tabla, se ve enseguida qué fue lo más elegido. Para no perder ninguna respuesta conviene ir marcando una rayita por cada dato y contarlas al final. Las frecuencias tienen que sumar la cantidad total de datos.",["Valor y frecuencia: cuántas veces aparece.","Las frecuencias suman el total."]),
 T("Partes de un todo en un círculo",D('circular'),DX('circular'),("Gráfico circular","El gráfico circular muestra cómo se reparte un total entre varias categorías: cada porción ocupa la parte del círculo que le corresponde a esa categoría."),"Si de 20 chicos 10 eligieron fútbol, la mitad de los votos es fútbol y ocupa la mitad del círculo, 180°. Para calcular cada porción se divide la frecuencia por el total y se multiplica por 360°. El gráfico de barras, en cambio, sirve mejor para comparar categorías entre sí, porque las alturas se ven lado a lado.",["10 de 20 → la mitad → 180°.","Porción = frecuencia ÷ total × 360°."]),
 T("Cómo cambia algo en el tiempo",D('lineas'),DX('lineas'),("Gráfico de líneas","El gráfico de líneas muestra cómo cambia un dato a lo largo del tiempo: se marca un punto por cada momento y se unen en orden."),"Así se ve de un vistazo cuándo algo sube, cuándo baja y cuándo se mantiene, como la temperatura durante la semana o la cantidad de lluvia de cada mes. La línea solo tiene sentido cuando los datos siguen un orden, por eso no se usa para comparar categorías como colores o deportes.",["Sube, baja o se mantiene.","Solo para datos ordenados en el tiempo."])],
 "recuerda":[R("Una tabla de frecuencias","ordena los datos indicando cuántas veces aparece cada valor.","Fútbol 10 · Vóley 6 · Tenis 4"),R("Las frecuencias de una tabla","suman siempre la cantidad total de datos registrados.","10 + 6 + 4 = 20"),R("En un gráfico circular","cada porción es la parte del total que le toca a una categoría.","10 de 20 → 180°"),R("El gráfico de líneas","muestra cómo cambia un dato con el tiempo, uniendo los puntos en orden.","Temperatura de lunes a jueves")]}
L['2']={"temas":[
 T("Un número que resume todos",D('media_moda'),DX('media_moda'),("Media y moda","La media, o promedio, se calcula sumando todos los datos y dividiendo por la cantidad de datos. La moda es el valor que más veces se repite."),"Las dos resumen un conjunto de datos, pero dicen cosas distintas. Si las notas de Luz son 7, 9, 7 y 5, la media es 28 ÷ 4 = 7 y la moda también es 7. Un valor muy distinto de los demás, como un 1 entre muchos 8, baja mucho la media pero no cambia la moda: por eso conviene mirar las dos antes de sacar conclusiones.",["Notas 7, 9, 7, 5: media 7, moda 7.","Si ningún valor se repite, no hay moda.","Cuidado: un valor extremo mueve la media."])],
 "recuerda":[R("La media de un conjunto de datos","se obtiene sumando todos los datos y dividiendo por la cantidad que hay.","7, 9, 7 y 5 → 28 ÷ 4 = 7"),R("La moda de un conjunto de datos","es el valor que aparece más veces en la lista.","7, 9, 7 y 5 → moda 7"),R("Un valor extremo","cambia mucho la media pero no cambia la moda de los datos.","8, 8, 8, 1 → media 6,25 · moda 8"),R("Si ningún valor se repite","el conjunto de datos no tiene moda.","3, 5, 8, 9 → sin moda")]}
L['3']={"temas":[
 T("¿Se puede saber antes?",D('azar'),DX('azar'),("Experimento de azar","Un experimento es de azar cuando se conocen todos los resultados posibles pero no se puede saber cuál va a salir antes de hacerlo, como tirar una moneda o un dado."),"Sumar 2 + 3 siempre da 5, así que no es de azar. Soltar una piedra siempre termina con la piedra en el piso. En cambio, al sacar una bolita de una bolsa sin mirar, puede salir cualquiera. Distinguirlos es el primer paso para hablar de probabilidades, porque solo tiene sentido calcularlas en experimentos de azar.",["Tirar un dado: azar.","Calcular el doble de 8: no es azar."]),
 T("Todos los resultados posibles",D('muestral'),DX('muestral'),("Espacio muestral y sucesos","El espacio muestral es la lista de todos los resultados posibles de un experimento de azar, y un suceso es una parte de esa lista que cumple una condición."),"Al tirar un dado, el espacio muestral es {1, 2, 3, 4, 5, 6}. El suceso «sale un número par» es {2, 4, 6}, y el suceso «sale más de 4» es {5, 6}. Escribir la lista completa evita olvidarse de algún caso, y contar cuántos resultados tiene cada suceso prepara el cálculo de probabilidades.",["Dado: E = {1, 2, 3, 4, 5, 6}.","«Par» = {2, 4, 6}."]),
 T("Contar combinaciones con una tabla",m('combinaciones_tabla'),m('combinaciones'),("Contar casos con una tabla","Cuando un experimento combina dos elecciones, como una remera y una gorra o dos monedas, los casos posibles se cuentan con una tabla de doble entrada: cada casilla es una combinación."),"Con 3 remeras y 2 gorras hay 3 × 2 = 6 combinaciones, porque cada remera puede ir con cada gorra. Al tirar dos monedas hay 4 casos: cara-cara, cara-ceca, ceca-cara y ceca-ceca. La tabla asegura que no falte ni se repita ninguno.",["3 remeras y 2 gorras: 6 combinaciones.","Dos monedas: 4 casos."])],
 "recuerda":[R("Un experimento de azar","tiene resultados conocidos, pero no se sabe cuál va a salir antes de hacerlo.","Tirar una moneda"),R("El espacio muestral","es la lista completa de todos los resultados posibles de un experimento.","Dado: {1, 2, 3, 4, 5, 6}"),R("Un suceso","es una parte del espacio muestral que cumple una condición.","«Sale par» = {2, 4, 6}"),R("Una tabla de doble entrada","sirve para contar todas las combinaciones de dos elecciones.","3 remeras × 2 gorras = 6")]}
L['4']={"temas":[
 T("Favorables sobre posibles",m('urna'),m('probabilidad'),("Probabilidad","La probabilidad de un suceso se calcula dividiendo la cantidad de casos favorables por la cantidad de casos posibles, siempre que todos los casos tengan la misma chance de salir."),"Si en una bolsa hay 3 bolitas rojas y 5 azules, la probabilidad de sacar una roja es 3/8: hay 3 casos favorables de 8 posibles. Ese número se puede escribir como fracción, como decimal (0,375) o como porcentaje (37,5 %). Siempre está entre 0 y 1: vale 0 si el suceso es imposible y 1 si es seguro, y las probabilidades de todos los colores suman 1.",["3 rojas y 5 azules: P(roja) = 3/8.","P = 0: imposible · P = 1: seguro."])],
 "recuerda":[R("La probabilidad de un suceso","se calcula dividiendo los casos favorables por los casos posibles.","3 rojas de 8 bolitas: 3/8",formula="P = favorables ÷ posibles"),R("Una probabilidad","se puede escribir como fracción, como decimal o como porcentaje.","3/8 = 0,375 = 37,5 %"),R("La probabilidad siempre está entre 0 y 1","y vale 0 si el suceso es imposible y 1 si es seguro.","Sacar una verde de una bolsa sin verdes: 0"),R("Las probabilidades de todos los resultados","de un experimento suman siempre 1.","3/8 + 5/8 = 1")]}
acts={'1':[{"t":"classify","n":"analizar","p":"Clasificá cada situación según el gráfico que conviene usar.","o":{"elementos":["La temperatura de cada día de la semana","Qué parte de la clase eligió cada deporte","Los ahorros de cada mes del año","Cómo se reparten los votos de una elección"],"categorias":["Gráfico de líneas","Gráfico circular"]},"r":{"categorias":{"La temperatura de cada día de la semana":"Gráfico de líneas","Qué parte de la clase eligió cada deporte":"Gráfico circular","Los ahorros de cada mes del año":"Gráfico de líneas","Cómo se reparten los votos de una elección":"Gráfico circular"}},"e":"Líneas: cambio en el tiempo. Circular: partes de un total."},{"t":"tap_text","n":"error","p":"[[error]] Juan armó un gráfico circular con 40 respuestas: 10 eligieron rojo. Tocá el paso que tiene un error.","o":{"segmentos":["10 de 40 es un cuarto del total","Un cuarto del círculo es 360° ÷ 4","La porción del rojo mide 40°"],"modo":"lineas"},"r":{"tocar":[2]},"e":"360° ÷ 4 = 90°: la porción mide 90°."}],
 '2':[{"t":"numeric","n":"aplicar","p":"[[problema]] Las notas de Mati en Matemática fueron 6, 8, 9 y 5. ¿Qué nota tiene que sacarse en la quinta prueba para que su media sea 7?","o":{},"r":{"acepta":[7]},"e":"Para media 7 en 5 notas la suma tiene que ser 35; ya tiene 28, le faltan 7."},{"t":"multiple_choice","n":"error","p":"[[comparar]] En un grupo, cuatro chicos tienen 12 años y uno tiene 40 (el profe). Tres chicos dicen qué representa mejor la edad típica del grupo. ¿Quién tiene razón?","o":["Ana: | la media, 17,6 años | es lo más justo","Beto: | la moda, 12 años | el 40 es un valor extremo","Caro: | el mayor, 40 años | manda el más grande"],"r":{"correcta":"Beto: | la moda, 12 años | el 40 es un valor extremo"},"e":"Un valor extremo sube mucho la media; la moda muestra mejor la edad típica."}],
 '3':[{"t":"ordering","n":"aplicar","p":"[[etapas]] Ordená los pasos para contar las combinaciones de 3 remeras y 2 gorras.","o":["Cada casilla es una combinación","Pongo las remeras en las filas","Cuento las casillas: 3 × 2 = 6","Pongo las gorras en las columnas"],"r":{"orden":["Pongo las remeras en las filas","Pongo las gorras en las columnas","Cada casilla es una combinación","Cuento las casillas: 3 × 2 = 6"]},"e":"Filas, columnas, casillas y contar."},{"t":"tap_text","n":"error","p":"[[error]] Sofi escribió el espacio muestral de tirar dos monedas. Tocá el paso que tiene un error.","o":{"segmentos":["Cada moneda puede salir cara (C) o ceca (X)","Los casos son CC, CX y XX","Hay 3 resultados posibles"],"modo":"lineas"},"r":{"tocar":[1]},"e":"Falta XC: CX y XC son distintos. Hay 4 casos."}],
 '4':[{"t":"classify","n":"analizar","p":"En una bolsa hay 4 bolitas rojas y ninguna verde. Clasificá cada suceso.","o":{"elementos":["Sacar una bolita roja","Sacar una bolita verde","Sacar una bolita de color"],"categorias":["Seguro (P = 1)","Imposible (P = 0)"]},"r":{"categorias":{"Sacar una bolita roja":"Seguro (P = 1)","Sacar una bolita verde":"Imposible (P = 0)","Sacar una bolita de color":"Seguro (P = 1)"}},"e":"Si todos los casos son favorables, P = 1; si ninguno, P = 0."},{"t":"multiple_choice","n":"error","p":"[[comparar]] En una bolsa hay 2 bolitas rojas y 6 azules. Tres chicos calcularon la probabilidad de sacar una roja. ¿Quién lo hizo bien?","o":["Ana: | rojas sobre azules | 2/6","Beto: | rojas sobre el total | 2/8 = 1/4","Caro: | hay dos colores | 1/2"],"r":{"correcta":"Beto: | rojas sobre el total | 2/8 = 1/4"},"e":"Casos posibles: todas las bolitas, 8. Los colores no tienen la misma chance."}]}
