  E[4][1]={"t":"ordering","n":"aplicar","p":"[[etapas]] Ordená los pasos para encontrar la moda de 6, 7, 7, 8, 9, 7, 10.","o":["El que más se repite es la moda: 7","Cuento cuántas veces aparece cada valor","Ordeno los datos: 6, 7, 7, 7, 8, 9, 10"],"r":{"orden":["Ordeno los datos: 6, 7, 7, 7, 8, 9, 10","Cuento cuántas veces aparece cada valor","El que más se repite es la moda: 7"]},"e":"Ordenar, contar y elegir el más repetido."}
  E[12][1]={"t":"classify","n":"aplicar","p":"Clasificá cada probabilidad según si es posible o no.","o":{"elementos":["1","0","3/8","1,5","−0,2","0,75"],"categorias":["Puede ser una probabilidad","No puede ser una probabilidad"]},"r":{"categorias":{"1":"Puede ser una probabilidad","0":"Puede ser una probabilidad","3/8":"Puede ser una probabilidad","1,5":"No puede ser una probabilidad","−0,2":"No puede ser una probabilidad","0,75":"Puede ser una probabilidad"}},"e":"Toda probabilidad está entre 0 y 1."}
